import { create } from 'zustand';
import { parsePrice } from './price';
import type { Product } from './api';

export type CartItem = { id: string; name: string; price: number; qty: number };

type Cart = { items: CartItem[]; add: (p: Product) => void; clear: () => void };

export const useCart = create<Cart>(set => ({
  items: [],
  add: p =>
    set(s => {
      const found = s.items.find(i => i.id === p.id);
      if (found) return { items: s.items.map(i => (i.id === p.id ? { ...i, qty: i.qty + 1 } : i)) };
      return { items: [...s.items, { id: p.id, name: p.name, price: parsePrice(p.price), qty: 1 }] };
    }),
  clear: () => set({ items: [] }),
}));

export function cartTotal(items: CartItem[]): number {
  return items.reduce((sum, i) => sum + i.price * i.qty, 0);
}
import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { getProduct, type Product as P } from '../api';
import { useCart } from '../cart';
import { formatPrice } from '../price';
import { PromoBadge } from '../PromoBadge';
import { daysAgo } from '../relative';
import type { ScreenProps } from '../routes';
import { Button } from '../ui';

export function Product({ route, navigation }: ScreenProps<'Product'>) {
  const [item, setItem] = useState<P | null>(null);
  const add = useCart(s => s.add);
  const count = useCart(s => s.items.reduce((n, i) => n + i.qty, 0));
  useEffect(() => {
    getProduct(route.params.id).then(r => setItem(r.body));
  }, [route.params.id]);
  if (!item) return <Text style={styles.loading}>Loading…</Text>;
  return (
    <View style={styles.page}>
      <View style={styles.picture} />
      <Text style={styles.title}>{item.name}</Text>
      <Text style={styles.price}>{formatPrice(item.price)}</Text>
